#!/usr/bin/env python3

import base64

import gi
gi.require_version("Gtk", "3.0")
gi.require_version("Gdk", "3.0")

from gi.repository import Gtk, Gdk, GdkPixbuf, GLib




LOGO_DATA = """
[]
"""



SPEED_X = 3
SPEED_Y = 3


FRAME_TIME = 16


class DVDDesktop(Gtk.Window):

    def __init__(self):
        super().__init__()


        self.set_type_hint(Gdk.WindowTypeHint.DESKTOP)


        self.set_decorated(False)


        self.set_accept_focus(False)
        self.set_focus_on_map(False)

 
        self.set_skip_taskbar_hint(True)
        self.set_skip_pager_hint(True)

 
        self.set_keep_below(True)

 

        self.override_background_color(
            Gtk.StateFlags.NORMAL,
            Gdk.RGBA(0, 0, 0, 1)
        )
      # shithead



        display = Gdk.Display.get_default()
        monitor = display.get_primary_monitor()

        if monitor is None:
        
            screen = Gdk.Screen.get_default()

            self.screen_width = screen.get_width()
            self.screen_height = screen.get_height()

            self.move(0, 0)

        else:
            geometry = monitor.get_geometry()

            self.screen_width = geometry.width
            self.screen_height = geometry.height

            self.move(
                geometry.x,
                geometry.y
            )

        self.set_default_size(
            self.screen_width,
            self.screen_height
        )



        try:
            logo_bytes = base64.b64decode(LOGO_DATA)

        except Exception as error:
            print("ERROR: Could not decode embedded logo.")
            print(error)
            raise SystemExit(1)



        try:
            loader = GdkPixbuf.PixbufLoader()

            loader.write(logo_bytes)
            loader.close()

            pixbuf = loader.get_pixbuf()

        except Exception as error:
            print("ERROR: Could not load embedded logo.")
            print(error)
            raise SystemExit(1)

        if pixbuf is None:
            print("ERROR: Embedded logo produced no image.")
            raise SystemExit(1)



        self.logo_width = pixbuf.get_width()
        self.logo_height = pixbuf.get_height()



        self.image = Gtk.Image.new_from_pixbuf(pixbuf)



        self.fixed = Gtk.Fixed()

        self.fixed.put(
            self.image,
            0,
            0
        )

        self.add(self.fixed)



        self.x = 100
        self.y = 100


        self.dx = SPEED_X
        self.dy = SPEED_Y



        self.connect(
            "destroy",
            Gtk.main_quit
        )



        self.show_all()



        GLib.timeout_add(
            FRAME_TIME,
            self.animate
        )

    def animate(self):



        self.x += self.dx
        self.y += self.dy



        if self.x <= 0:

            self.x = 0
            self.dx *= -1

        elif self.x + self.logo_width >= self.screen_width:

            self.x = self.screen_width - self.logo_width
            self.dx *= -1



        if self.y <= 0:

            self.y = 0
            self.dy *= -1

        elif self.y + self.logo_height >= self.screen_height:

            self.y = self.screen_height - self.logo_height
            self.dy *= -1



        self.fixed.move(
            self.image,
            int(self.x),
            int(self.y)
        )


        return True




if __name__ == "__main__":

    app = DVDDesktop()

    Gtk.main()
